function detail(id) {
  const item = properties().find(p => p.id === id);
  if (!item) return `${header()}<main id="content" class="section detail"><div class="shell"><h1>Bien indisponible</h1><a href="#/biens">Voir les biens disponibles</a></div></main>${footer()}`;
  const units = Array.isArray(item.units) ? item.units : [];
  const selectedIndex = Math.max(0,units.findIndex(unit=>unit.status==='Available'));
  const selectedUnit = units[selectedIndex];
  const unitValue = (key,fallback) => selectedUnit?.[key] == null || selectedUnit[key] === '' ? fallback : selectedUnit[key];
  const gallery = (selectedUnit?.images?.filter(Boolean).length ? selectedUnit.images : item.images).filter(Boolean);
  const detailPrice = money({...item,price:unitValue('price',item.price)});
  const related = properties().filter(p => p.id !== item.id).slice(0, 3);
  const unitSelector = units.length ? `<section class="unit-selector" aria-label="Unités et appartements disponibles"><div class="unit-selector-head"><div><p class="eyebrow">Unités disponibles</p><h2>${availableUnitsText(item)}</h2></div>${units.length>1?'<p>Sélectionnez une surface pour consulter ses détails.</p>':''}</div>${units.length>1?`<div class="unit-options">${units.map((unit,index)=>`<button class="filter unit-option ${index===selectedIndex?'active':''}" type="button" data-unit-index="${index}" ${unit.status==='Available'?'':'disabled'} aria-pressed="${index===selectedIndex}"><span>${unit.area ?? item.area} m²</span><small>${unit.name}${unit.status==='Available'?'':' · Indisponible'}</small></button>`).join('')}</div>`:''}</section>` : '';
  return `${header()}<main id="content" class="detail" data-property-id="${item.id}"><div class="shell"><p class="crumbs"><a href="#/biens">Biens disponibles</a> / ${typeLabel(item.type)}</p><div class="detail-title"><div><p class="eyebrow">${item.category==='prestige'?'Prestige · ':''}${typeLabel(item.type)} · <span id="unit-status">${statusLabel(unitValue('status',item.status))}</span> · ${item.transaction === "Rent" ? "Location" : "Vente"}</p><h1>${item.title}</h1><p>${svg.pin} ${item.location}, Oran</p></div><div class="detail-price"><span id="unit-price">${detailPrice}</span><br><small style="font-size:.72rem;color:var(--copy);font-weight:400">Honoraires sur demande</small></div></div>${unitSelector}<section class="gallery">${gallery.map((image, index) => `<div><img src="${image}" alt="${item.title} — vue ${index + 1}"></div>`).join('')}</section><section class="detail-grid"><article><h2>Un lieu conçu pour bien vivre.</h2><div class="property-description">${descriptionHtml(item.description)}</div><div class="facts"><div><b id="unit-beds">${unitValue('beds',item.beds)}</b>Chambres</div><div><b>${item.baths}</b>Salles de bain</div><div><b id="unit-area">${unitValue('area',item.area)} m²</b>Surface</div><div><b id="unit-floor">${units.length?unitValue('floor',item.floor??'—'):item.parking??'—'}</b><span id="unit-fourth-label">${units.length?'Étage':'Parking'}</span></div></div><h3>Les points forts</h3><p>${(item.features || []).join(" · ") || "Contactez-nous pour plus de détails."}</p></article>${inquiryForm(item.title)}</section></div><section class="map-block"><div class="shell map-grid"><div><p class="eyebrow">Localisation</p><h2 class="display">Découvrir le quartier</h2><p class="lede">Une adresse privilégiée dans l’aire urbaine d’Oran, sélectionnée pour son cadre de vie et son accessibilité.</p></div><iframe class="map" title="Carte de ${item.location}" loading="lazy" src="https://www.google.com/maps?q=${encodeURIComponent(item.mapLocation || item.location + ', Algeria')}&output=embed"></iframe></div></section><section class="section properties"><div class="shell"><div class="center"><p class="eyebrow">À découvrir aussi</p><h2 class="display">Biens similaires</h2></div><div class="cards">${related.map(propertyCard).join('')}</div></div></section></main>${footer()}`;
}
