function bindGlobal() {
  applyPreferences();
  const navBar = $('.nav');
  if (navBar && !$('#site-controls')) {
    const language = getLanguage();
    const theme = getTheme();
    navBar.insertAdjacentHTML('beforeend', `<div id="site-controls" class="site-controls"><button class="language-toggle" type="button" aria-label="Changer la langue" title="Changer la langue">${language === 'fr' ? 'ع' : 'FR'}</button><button class="theme-toggle" type="button" aria-label="Activer le mode ${theme === 'dark' ? 'jour' : 'nuit'}" title="Mode jour / nuit"><span>${theme === 'dark' ? '☀' : '☾'}</span></button></div>`);
    $('.language-toggle').addEventListener('click', () => {
      localStorage.setItem('kader-language', getLanguage() === 'fr' ? 'ar' : 'fr');
      render();
    });
    $('.theme-toggle').addEventListener('click', () => {
      localStorage.setItem('kader-theme', getTheme() === 'light' ? 'dark' : 'light');
      applyPreferences();
      render();
    });
  }
  const agencyMap = $('.map[title="Localisation de l’Agence immobilière Kader à Oran"]');
  if (agencyMap) {
    agencyMap.src = 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3238.787827517757!2d-0.5801798234376989!3d35.73143627257105!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0xd7e630036a4fce9%3A0x17d102017e08891f!2sAgence%20immobili%C3%A8re%20Kader!5e0!3m2!1sen!2sdz!4v1788969335248!5m2!1sen!2sdz';
    agencyMap.setAttribute('allowfullscreen', '');
    agencyMap.setAttribute('referrerpolicy', 'strict-origin-when-cross-origin');
  }
  const menu = $('.hamburger');
  if (menu) menu.addEventListener('click', () => {
    const nav = $('.mobile-nav');
    const open = nav.classList.toggle('show');
    menu.innerHTML = open ? svg.close : svg.menu;
    menu.setAttribute('aria-expanded', String(open));
  });
  const route = currentRoute();
  $$('.navlinks a').forEach(link => link.classList.toggle('active', link.getAttribute('href') === `#${route}` || (route.startsWith('/bien/') && link.getAttribute('href') === '#/biens')));
}
function bindForms() {
  $$('.validate-form').forEach(form => form.addEventListener('submit', event => {
    event.preventDefault();
    $$('.error', form).forEach(error => error.remove());
    let valid = true;
    $$('[required]', form).forEach(input => {
      const invalidEmail = input.type === 'email' && !/^\S+@\S+\.\S+$/.test(input.value);
      if (!input.value.trim() || invalidEmail) {
        valid = false;
        input.setAttribute('aria-invalid', 'true');
        input.insertAdjacentHTML('afterend', '<span class="error">Veuillez renseigner ce champ correctement.</span>');
      } else input.removeAttribute('aria-invalid');
    });
    if (valid) {
      const values = Object.fromEntries(new FormData(form));
      const text = `${values.name}\n${values.email}\n${values.subject || ''}\n${values.message}`;
      $('.form-result', form).innerHTML = '<p>Votre message est prêt. Ouvrez WhatsApp puis confirmez l’envoi.</p><a class="btn btn-ink" target="_blank" rel="noreferrer" href="https://wa.me/213796265326?text='+encodeURIComponent(text)+'">Continuer sur WhatsApp</a>';
    }
  }));
}
function bindListings() {
  const grid = $('#property-grid');
  if (!grid) return;
  let selected = currentRoute() === '/biens/prestige' ? 'Prestige' : 'Tous';
  let term = '';
  function draw() {
    const result = properties().filter(p => (selected === 'Tous' || (selected === 'Prestige' ? p.category === 'prestige' : p.type === selected)) && `${p.title} ${p.location}`.toLowerCase().includes(term.toLowerCase()));
    grid.innerHTML = result.length ? result.map(propertyCard).join('') : '<p>Aucun bien ne correspond à votre recherche.</p>';
    $('#property-count').textContent = `${result.length} bien${result.length > 1 ? 's' : ''} disponible${result.length > 1 ? 's' : ''}`;
  }
  $$('.filter').forEach(button => button.addEventListener('click', () => {
    selected = button.dataset.filter;
    $$('.filter').forEach(item => item.classList.toggle('active', item === button));
    draw();
  }));
  $('#property-search').addEventListener('input', event => { term = event.target.value; draw(); });
  draw();
}
function bindUnits() {
  const detailPage=$('.detail[data-property-id]'),options=$$('.unit-option');
  if(!detailPage||!options.length)return;
  const item=properties().find(property=>property.id===detailPage.dataset.propertyId);
  if(!item)return;
  options.forEach(button=>button.addEventListener('click',()=>{
    const unit=item.units[Number(button.dataset.unitIndex)];if(!unit||unit.status!=='Available')return;
    options.forEach(option=>{const active=option===button;option.classList.toggle('active',active);option.setAttribute('aria-pressed',String(active));});
    $('#unit-price').textContent=money({...item,price:unit.price??item.price});
    $('#unit-status').textContent=statusLabel(unit.status);
    $('#unit-beds').textContent=unit.beds??item.beds;
    $('#unit-area').textContent=(unit.area??item.area)+' m²';
    $('#unit-floor').textContent=unit.floor??item.floor??'—';
    const images=unit.images?.filter(Boolean).length?unit.images:item.images;
    $('.gallery').innerHTML=images.filter(Boolean).map((image,index)=>`<div><img src="${image}" alt="${item.title} — vue ${index+1}"></div>`).join('');
  }));
}
function toast(message) {
  document.body.insertAdjacentHTML('beforeend', `<div class="toast" role="status">${message}</div>`);
  setTimeout(() => $('.toast')?.remove(), 2600);
}
/* ── Kader Immo administration workspace ─────────────────────────────── */
const dashIcons = { dashboard:'⌘', listings:'▦', plus:'＋', people:'◎', messages:'◌', content:'▤', finance:'◫', analytics:'⌁', settings:'⚙', bell:'●', search:'⌕', sun:'☼', more:'•••', preview:'↗' };
const listingStatus = item => item.status || 'Draft';
const statusClass = status => ({Available:'available',Published:'published',Sold:'sold',Rented:'rented',Reserved:'rented',Draft:'draft'})[status] || 'draft';
const reference = item => item.ref || 'KIM-' + crypto.randomUUID().slice(0,8).toUpperCase();
const money = item => Number(item.price).toLocaleString('fr-DZ') + ' ' + (item.currency || 'DA');
const statusLabels = {Available:'Disponible',Sold:'Vendu',Rented:'Loué',Reserved:'Réservé',Draft:'Brouillon',Published:'Publié',Unpublished:'Non publié',Archived:'Archivé'};
const typeLabels = {Apartment:'Appartement',Villa:'Villa',House:'Maison',Maison:'Maison',Duplex:'Duplex',Land:'Terrain',Commercial:'Local commercial',Office:'Bureau',Other:'Autre'};
const transactionLabels = {Sale:'Vente',Rent:'Location'};
const categoryLabels = {standard:'Standard',prestige:'Prestige'};
const featureLabels = {Balcony:'Balcon',Terrace:'Terrasse',Garden:'Jardin',Garage:'Garage',Elevator:'Ascenseur','Air conditioning':'Climatisation',Furnished:'Meublé',Security:'Sécurité','Sea view':'Vue sur mer',Pool:'Piscine'};
const statusLabel = value => statusLabels[value] || value;
const typeLabel = value => typeLabels[value] || value;
const transactionLabel = value => transactionLabels[value] || value;
const categoryLabel = value => categoryLabels[value] || categoryLabels.standard;
const availableUnitCount = item => (Array.isArray(item.units)?item.units:[]).filter(unit=>unit.status==='Available').length;
const availableUnitsText = item => {const count=availableUnitCount(item);return count===1?'1 appartement disponible':`${count} appartements disponibles`;};
function dashSidebar(active) {
  const primary = [['dashboard','Tableau de bord'],['listings','Biens'],['add','Ajouter un bien'],['media','Médiathèque']];
  return `<aside class="dash-sidebar" id="dash-sidebar"><div class="dash-brand"><img class="dash-logo" src="/assets/kader-logo.png" width="1254" height="1254" alt="Kader Immo"><button class="close-drawer" aria-label="Fermer le menu">×</button></div><nav>${primary.map(([key,label])=>`<a href="#/admin/${key === 'add' ? 'editor' : key}" class="${active===key?'active':''}"><i>${dashIcons[key]||dashIcons.listings}</i><span>${label}</span></a>`).join('')}<a href="#/admin/settings"><i>${dashIcons.settings}</i><span>Paramètres</span></a></nav><div class="sidebar-bottom"><a href="#/admin/support"><i>?</i><span>Aide et assistance</span></a><button class="profile-button"><span class="avatar">HK</span><span><b>Administrateur</b><small>Administrateur</small></span><em>⌄</em></button></div></aside>`;
}
function dashTopbar() {
  return `<header class="dash-topbar"><button class="drawer-toggle" aria-label="Ouvrir le menu">☰</button><label class="global-search">${dashIcons.search}<input id="global-search" placeholder="Rechercher un bien, un lieu ou une référence…" autocomplete="off"><kbd>⌘ K</kbd></label><div class="dash-tools"><button id="dash-theme" title="Changer de thème">${dashIcons.sun}</button><button class="dash-user"><span class="avatar">HK</span><span>Compte</span>⌄</button></div></header>`;
}
function dashShell(active, body) { return `<main class="dashboard-app">${dashSidebar(active)}<section class="dash-main">${dashTopbar()}<div class="dash-content">${body}</div></section></main>`; }
function kpi(label, value, trend, icon, extra) { return `<article class="kpi-card"><div><p>${label}</p><strong>${value}</strong><small>Total actuel dans la base</small></div><span class="kpi-icon">${icon}</span>${extra||''}</article>`; }
function chart() { return `<div class="chart-card dash-card"><div class="card-head"><div><h2>Aperçu du portefeuille</h2><p>Biens actuellement enregistrés sur votre site</p></div></div><div class="cms-overview">${['Villa','Duplex','Maison','Apartment','House','Land','Commercial','Office','Other'].filter(t=>properties().some(p=>p.type===t)).map(t=>`<p><b>${typeLabel(t)}</b><span>${properties().filter(p=>p.type===t).length} bien${properties().filter(p=>p.type===t).length>1?'s':''}</span></p>`).join('') || '<p>Aucun bien enregistré.</p>'}</div></div>`; }
function distribution(items) { const total = items.length || 1; const counts = ['Available','Sold','Rented','Draft'].map(status => [status,items.filter((p,i)=>listingStatus(p,i)===status).length]); return `<div class="status-card dash-card"><div class="card-head"><div><h2>Statut des biens</h2><p>Répartition du portefeuille</p></div></div><div class="donut" style="--a:${counts[0][1]/total*360}deg;--b:${(counts[0][1]+counts[1][1])/total*360}deg;--c:${(counts[0][1]+counts[1][1]+counts[2][1])/total*360}deg"><span><b>${items.length}</b>Total</span></div><div class="legend">${counts.map(([s,c])=>`<span><i class="${statusClass(s)}"></i>${statusLabel(s)}<b>${Math.round(c/total*100)}%</b></span>`).join('')}</div></div>`; }
function listingsRows(items, compact=false) { return items.map((p,i)=>`<tr data-listing="${p.id}"><td><div class="listing-name"><img src="${p.image}" alt=""><span><b>${p.title}</b><small>${reference(p)}</small></span></div></td><td class="hide-on-mobile">${p.location}</td><td class="hide-on-tablet">${typeLabel(p.type||'Villa')}</td><td class="hide-on-tablet">${money(p)}</td><td><span class="status ${statusClass(listingStatus(p,i))}">${statusLabel(listingStatus(p,i))}</span><small class="cms-visibility">${p.archived?'Archivé':p.published?'Publié':'Non publié'}${p.featured?' · À la une':''} · ${categoryLabel(p.category)}${p.units?.length?' · '+availableUnitsText(p):''}</small></td><td class="hide-on-mobile">${displayDate(p.updatedAt)}</td><td><div class="row-actions"><button data-action="preview" data-id="${p.id}" title="Aperçu">${dashIcons.preview}</button><button data-action="edit" data-id="${p.id}" title="Modifier">✎</button><button data-action="more" data-id="${p.id}" title="Plus d’actions">${dashIcons.more}</button></div></td></tr>`).join(''); }
function dashboardHome() {
 const items=properties(), published=items.filter((p,i)=>p.published && !p.archived).length, available=items.filter((p,i)=>listingStatus(p,i)==='Available').length, closed=items.filter((p,i)=>['Sold','Rented'].includes(listingStatus(p,i))).length;
 return dashShell('dashboard',`<div class="dash-page-head"><div><p class="page-kicker">VUE D’ENSEMBLE</p><h1>Tableau de bord</h1><p>Bienvenue. Voici l’état actuel de vos biens immobiliers.</p></div><div class="head-actions"><button class="ghost-button">⇩ Exporter</button></div></div><section class="kpi-grid">${kpi('Total des biens',items.length,'+12.5%','▦')}${kpi('Publiés',published,'+8.2%','◉')}${kpi('Disponibles',available,'+4.7%','⌂')}${kpi('Vendus / Loués',closed,'+16.4%','✓')}</section><section class="dash-split">${chart()}${distribution(items)}</section><section class="dash-card recent-card"><div class="card-head"><div><h2>Biens récents</h2><p>Biens ajoutés ou modifiés récemment</p></div><a href="#/admin/listings" class="text-link">Voir tous les biens →</a></div><div class="table-wrap"><table class="listing-table"><thead><tr><th>Bien</th><th class="hide-on-mobile">Localisation</th><th class="hide-on-tablet">Type</th><th class="hide-on-tablet">Prix</th><th>Statut</th><th class="hide-on-mobile">Dernière modification</th><th></th></tr></thead><tbody>${listingsRows(items.slice(0,5))}</tbody></table></div></section>`);
}
function listingFilters() { return `<div class="listing-filters"><label class="listing-search">${dashIcons.search}<input id="listing-search" placeholder="Rechercher par nom, référence, lieu ou type"></label><button class="filter-control" data-filter-menu>Statut <b>Tous</b>⌄</button><button class="filter-control" data-filter-menu>Type de bien⌄</button><button class="filter-control" data-filter-menu>Transaction⌄</button><button class="filter-control" data-filter-menu>Plus de filtres⌄</button><button class="view-switch active" data-view="table" aria-label="Vue en tableau">☷</button><button class="view-switch" data-view="grid" aria-label="Vue en grille">▦</button></div>`; }
function listingManagement() { const items=properties(); return dashShell('listings',`<div class="dash-page-head"><div><p class="page-kicker">PROPERTY MANAGEMENT</p><h1>Listings</h1><p>Manage the properties displayed on your website.</p></div><div class="head-actions"><button class="ghost-button">⇩ Export</button><a class="primary-button" href="#/admin/editor">＋ Add Property</a></div></div>${listingFilters()}<div class="dash-card listing-management"><div class="management-summary"><b>${items.length} listings</b><span>Sorted by last updated</span></div><div class="table-wrap table-view"><table class="listing-table"><thead><tr><th>Property</th><th class="hide-on-mobile">Location</th><th class="hide-on-tablet">Type</th><th class="hide-on-tablet">Price</th><th>Status</th><th class="hide-on-mobile">Last updated</th><th></th></tr></thead><tbody id="management-list">${listingsRows(items)}</tbody></table></div><div class="listing-grid-view hidden" id="listing-grid-view">${items.map((p,i)=>`<article class="admin-property-card"><img src="${p.image}" alt=""><div><span class="status ${statusClass(listingStatus(p,i))}">${listingStatus(p,i)}</span><h3>${p.title}</h3><small>${reference(p)} · ${p.location}</small><p>${money(p)}</p><span>${p.area} · ${p.beds} beds · ${p.baths} baths</span></div><button data-action="edit" data-id="${p.id}">Edit listing →</button></article>`).join('')}</div></div>`);
}
function featureTokens(selected=[]) { const options=['Balcony','Terrace','Garden','Garage','Elevator','Air conditioning','Furnished','Security','Sea view','Pool']; return `<div class="feature-list">${options.map(option=>`<button type="button" class="feature-token ${selected.includes(option)?'selected':''}" data-feature="${option}">${selected.includes(option)?'✓ ':''}${option}</button>`).join('')}<button type="button" class="feature-token custom-feature">＋ Add custom</button></div>`; }
function editorPage(id) { const item=id ? properties().find(p=>p.id===id) : null; if (id && !item) return dashShell('listings','<h1>Property not found</h1><a href="#/admin/listings">Back to listings</a>'); const p=item||{title:'',ref:'',type:'Villa',transaction:'Sale',status:'Draft',price:'',location:'',wilaya:'Oran',city:'Oran',neighborhood:'',address:'',area:'',beds:'',baths:'',floor:'',floors:'',parking:'',year:'',description:'',images:[],features:[]}; const images=p.images?.length?p.images:[p.image].filter(Boolean); return dashShell('add',`<div class="editor-page-head"><div><a class="back-link" href="#/admin/listings">← Back to listings</a><div class="title-line"><h1>${item?'Edit property':'Add property'}</h1><span class="status ${statusClass(p.status)}">${p.status||'Draft'}</span></div><p>${item?`${reference(p)} · Updated ${displayDate(p.updatedAt)}`:'Create a property listing for the Kader Immo website.'}</p></div><div class="head-actions"><button class="ghost-button" data-preview-editor>↗ Preview Listing</button></div></div><form id="property-editor-v2" data-id="${p.id||''}" novalidate><div class="editor-layout"><div class="editor-stack"><section class="editor-section"><div class="section-title"><span class="section-number">01</span><div><h2>Basic information</h2><p>The essentials that identify this property.</p></div></div><div class="form-grid"><label class="form-wide">Property title<input name="title" value="${p.title}" required placeholder="e.g. Villa contemporaine à Canastel"></label><label>Reference ID<input name="ref" value="${p.ref||reference(p)}" required></label><label>Property type<select name="type">${['Apartment','Villa','House','Maison','Duplex','Land','Commercial','Office','Other'].map(x=>`<option ${p.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Transaction type<select name="transaction"><option ${p.transaction==='Sale'?'selected':''}>Sale</option><option ${p.transaction==='Rent'?'selected':''}>Rent</option></select></label><label>Availability<select name="status">${['Draft','Available','Sold','Rented'].map(x=>`<option ${p.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Price<input name="price" value="${p.price}" placeholder="65 000 000" required></label><label>Currency<select name="currency">${['DA','EUR','USD'].map(x=>`<option ${p.currency===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="cms-check"><input type="checkbox" name="featured" ${p.featured?'checked':''}> Featured on homepage</label><label class="cms-check"><input type="checkbox" name="published" ${p.published?'checked':''}> Visible on public website</label></div></section><section class="editor-section"><div class="section-title"><span class="section-number">02</span><div><h2>Location</h2><p>Help clients find this property.</p></div></div><div class="form-grid"><label>Wilaya<input name="wilaya" value="${p.wilaya||'Oran'}"></label><label>City<input name="city" value="${p.city||'Oran'}"></label><label>Neighborhood<input name="neighborhood" value="${p.neighborhood||p.location}"></label><label class="form-wide">Address<input name="address" value="${p.address||''}" placeholder="Street and number (optional)"></label></div><label class="cms-map-label">Google Maps coordinates or place<input name="mapLocation" value="${p.mapLocation || p.location || ''}" placeholder="35.7314, -0.5802"></label><div class="location-map"><iframe title="Select property location" loading="lazy" src="https://www.google.com/maps?q=${encodeURIComponent((p.location||'Oran')+', Algeria')}&output=embed"></iframe><button type="button">◎ Set map location</button></div></section><section class="editor-section"><div class="section-title"><span class="section-number">03</span><div><h2>Property details</h2><p>Precise characteristics build buyer confidence.</p></div></div><div class="form-grid details-grid"><label>Surface area (m²)<input name="area" value="${String(p.area).replace(' m²','')}" type="number"></label><label>Bedrooms<input name="beds" value="${p.beds}" type="number"></label><label>Bathrooms<input name="baths" value="${p.baths}" type="number"></label><label>Floor<input name="floor" value="${p.floor||''}" type="number"></label><label>Number of floors<input name="floors" value="${p.floors||''}" type="number"></label><label>Parking spaces<input name="parking" value="${p.parking||''}" type="number"></label><label>Year built<input name="year" value="${p.year||''}" type="number"></label></div></section><section class="editor-section"><div class="section-title"><span class="section-number">04</span><div><h2>Description</h2><p>Tell the story of this property.</p></div></div><div class="rich-toolbar"><button type="button">B</button><button type="button"><i>I</i></button><button type="button">H</button><button type="button">☷</button><span></span><button type="button">↶</button></div><textarea class="rich-text" name="description" required placeholder="Write a clear, compelling property description...">${p.description||''}</textarea></section><section class="editor-section"><div class="section-title"><span class="section-number">05</span><div><h2>Features</h2><p>Select the amenities offered by this listing.</p></div></div>${featureTokens(p.features||[])}</section></div><aside class="editor-side"><section class="media-section"><div class="side-title"><div><h2>Property images</h2><p>Drag to reorder. First image is the cover.</p></div></div><div class="media-grid" id="media-grid">${images.map((url,i)=>`<figure draggable="true" data-image-index="${i}" data-path="${p.imagePaths?.[i] || ''}"><img src="${url}" alt=""><figcaption>${i===0?'Cover Image':'Image '+(i+1)}</figcaption><button type="button" class="remove-media" data-remove-image="${i}" aria-label="Remove image">×</button></figure>`).join('')}<label class="upload-tile">＋<input id="image-uploader" type="file" accept="image/*" multiple hidden><span>Upload images</span></label></div></section><section class="publish-box"><span class="publish-icon">↥</span><h3>Ready to publish?</h3><p>Published listings are immediately visible on your public Kader Immo website.</p><button class="primary-button full" type="submit" data-save="publish">Publish Listing</button><button class="ghost-button full" type="submit" data-save="draft">Save Draft</button></section><section class="activity-box"><h3>Listing activity</h3><div><span>Created</span><b>${displayDate(p.createdAt)}</b></div><div><span>Last modified</span><b>${displayDate(p.updatedAt)}</b></div><div><span>Published</span><b>${displayDate(p.publishedAt)}</b></div></section></aside></div><div class="editor-footer"><a href="#/admin/listings">Cancel</a><div><button type="submit" class="ghost-button" data-save="draft">Save Draft</button><button type="submit" class="primary-button" data-save="changes">Save Changes</button></div></div></form>`);
}
function listingManagementFr() {
  const items=properties();
  return dashShell('listings',`<div class="dash-page-head"><div><p class="page-kicker">GESTION DES BIENS</p><h1>Biens</h1><p>Gérez les biens affichés sur votre site internet.</p></div><div class="head-actions"><button class="ghost-button">⇩ Exporter</button><a class="primary-button" href="#/admin/editor">＋ Ajouter un bien</a></div></div>${listingFilters()}<div class="dash-card listing-management"><div class="management-summary"><b>${items.length} bien${items.length>1?'s':''}</b><span>Triés par dernière modification</span></div><div class="table-wrap table-view"><table class="listing-table"><thead><tr><th>Bien</th><th class="hide-on-mobile">Localisation</th><th class="hide-on-tablet">Type</th><th class="hide-on-tablet">Prix</th><th>Statut</th><th class="hide-on-mobile">Dernière modification</th><th></th></tr></thead><tbody id="management-list">${listingsRows(items)}</tbody></table></div><div class="listing-grid-view hidden" id="listing-grid-view">${items.map((p,i)=>`<article class="admin-property-card"><img src="${p.image}" alt=""><div><span class="status ${statusClass(listingStatus(p,i))}">${statusLabel(listingStatus(p,i))}</span><h3>${p.title}</h3><small>${reference(p)} · ${p.location}</small><p>${money(p)}</p><span>${typeLabel(p.type)} · ${categoryLabel(p.category)} · ${p.area} m² · ${p.beds} ch. · ${p.baths} sdb</span></div><button data-action="edit" data-id="${p.id}">Modifier le bien →</button></article>`).join('') || '<p>Aucun bien enregistré.</p>'}</div></div>`);
}
function featureTokensFr(selected=[]) {
  const options=['Balcony','Terrace','Garden','Garage','Elevator','Air conditioning','Furnished','Security','Sea view','Pool'];
  return `<div class="feature-list">${options.map(option=>`<button type="button" class="feature-token ${selected.includes(option)?'selected':''}" data-feature="${option}">${selected.includes(option)?'✓ ':''}${featureLabels[option]}</button>`).join('')}<button type="button" class="feature-token custom-feature">＋ Ajouter un équipement</button></div>`;
}
function editorPageFr(id) {
  const item=id ? properties().find(p=>p.id===id) : null;
  if(id&&!item)return dashShell('listings','<h1>Bien introuvable</h1><a href="#/admin/listings">Retour aux biens</a>');
  const p=item||{title:'',ref:'',type:'Villa',category:'standard',transaction:'Sale',status:'Draft',price:'',location:'',wilaya:'Oran',city:'Oran',neighborhood:'',address:'',area:'',beds:'',baths:'',floor:'',floors:'',parking:'',year:'',description:'',images:[],features:[],units:[]};
  const images=p.images?.length?p.images:[p.image].filter(Boolean);
  const typeOptions=['Apartment','Villa','House','Maison','Duplex','Land','Commercial','Office','Other'].map(x=>`<option value="${x}" ${p.type===x?'selected':''}>${typeLabel(x)}</option>`).join('');
  const statusOptions=['Draft','Available','Sold','Rented'].map(x=>`<option value="${x}" ${p.status===x?'selected':''}>${statusLabel(x)}</option>`).join('');
  return dashShell('add',`<div class="editor-page-head"><div><a class="back-link" href="#/admin/listings">← Retour aux biens</a><div class="title-line"><h1>${item?'Modifier le bien':'Ajouter un bien'}</h1><span class="status ${statusClass(p.status)}">${statusLabel(p.status||'Draft')}</span></div><p>${item?`${reference(p)} · Mis à jour le ${displayDate(p.updatedAt)}`:'Créez un bien à publier sur le site Kader Immo.'}</p></div><div class="head-actions"><button class="ghost-button" data-preview-editor>↗ Aperçu du bien</button></div></div>
  <form id="property-editor-v2" data-id="${p.id||''}" novalidate><div class="editor-layout"><div class="editor-stack">
  <section class="editor-section"><div class="section-title"><span class="section-number">01</span><div><h2>Informations générales</h2><p>Les informations essentielles qui identifient ce bien.</p></div></div><div class="form-grid"><label class="form-wide">Titre du bien<input name="title" value="${p.title}" required placeholder="Ex. : Villa contemporaine à Canastel"></label><label>Référence<input name="ref" value="${p.ref||reference(p)}" required></label><label>Type de bien<select name="type">${typeOptions}</select></label><label>Catégorie du bien<select name="category"><option value="standard" ${p.category!=='prestige'?'selected':''}>Standard</option><option value="prestige" ${p.category==='prestige'?'selected':''}>Prestige</option></select></label><label>Type de transaction<select name="transaction"><option value="Sale" ${p.transaction==='Sale'?'selected':''}>Vente</option><option value="Rent" ${p.transaction==='Rent'?'selected':''}>Location</option></select></label><label>Disponibilité<select name="status">${statusOptions}</select></label><label>Prix<input name="price" value="${p.price}" placeholder="65 000 000" required></label><label>Devise<select name="currency">${['DA','EUR','USD'].map(x=>`<option ${p.currency===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="cms-check"><input type="checkbox" name="featured" ${p.featured?'checked':''}> Mettre à la une sur l’accueil</label><label class="cms-check"><input type="checkbox" name="published" ${p.published?'checked':''}> Visible sur le site public</label></div></section>
  <section class="editor-section"><div class="section-title"><span class="section-number">02</span><div><h2>Localisation</h2><p>Aidez les clients à situer ce bien.</p></div></div><div class="form-grid"><label>Wilaya<input name="wilaya" value="${p.wilaya||'Oran'}"></label><label>Ville<input name="city" value="${p.city||'Oran'}"></label><label>Quartier<input name="neighborhood" value="${p.neighborhood||p.location}"></label><label class="form-wide">Adresse<input name="address" value="${p.address||''}" placeholder="Rue et numéro (facultatif)"></label></div><label class="cms-map-label">Coordonnées ou lieu Google Maps<input name="mapLocation" value="${p.mapLocation||p.location||''}" placeholder="35.7314, -0.5802"></label><div class="location-map"><iframe title="Choisir la localisation du bien" loading="lazy" src="https://www.google.com/maps?q=${encodeURIComponent((p.location||'Oran')+', Algeria')}&output=embed"></iframe><button type="button">◎ Actualiser la carte</button></div></section>
  <section class="editor-section"><div class="section-title"><span class="section-number">03</span><div><h2>Caractéristiques du bien</h2><p>Des informations précises renforcent la confiance des clients.</p></div></div><div class="form-grid details-grid"><label>Surface (m²)<input name="area" value="${String(p.area).replace(' m²','')}" type="number"></label><label>Chambres<input name="beds" value="${p.beds}" type="number"></label><label>Salles de bain<input name="baths" value="${p.baths}" type="number"></label><label>Étage<input name="floor" value="${p.floor||''}" type="number"></label><label>Nombre d’étages<input name="floors" value="${p.floors||''}" type="number"></label><label>Places de stationnement<input name="parking" value="${p.parking||''}" type="number"></label><label>Année de construction<input name="year" value="${p.year||''}" type="number"></label></div></section>
  <section class="editor-section unit-editor-section"><div class="section-title"><span class="section-number">04</span><div><h2>Unités / Appartements disponibles</h2><p>Ajoutez uniquement des unités lorsque cette annonce représente un projet avec plusieurs appartements.</p></div></div><div class="unit-editor-summary"><strong id="available-unit-count">0 appartement disponible</strong><span>Calculé automatiquement selon le statut des unités.</span></div><div class="unit-editor-list" id="unit-editor-list"></div><button class="ghost-button add-unit-button" id="add-unit" type="button">＋ Ajouter une unité</button></section>
  <section class="editor-section"><div class="section-title"><span class="section-number">05</span><div><h2>Description</h2><p>Présentez clairement les atouts de ce bien.</p></div></div><div class="rich-toolbar"><button type="button">B</button><button type="button"><i>I</i></button><button type="button">H</button><button type="button">☷</button><span></span><button type="button">↶</button></div><textarea class="rich-text" name="description" required placeholder="Rédigez une description claire et attractive du bien…">${p.description||''}</textarea></section>
  <section class="editor-section"><div class="section-title"><span class="section-number">06</span><div><h2>Équipements</h2><p>Sélectionnez les équipements proposés avec ce bien.</p></div></div>${featureTokensFr(p.features||[])}</section></div>
  <aside class="editor-side"><section class="media-section"><div class="side-title"><div><h2>Photos du bien</h2><p>Faites glisser les photos pour les réorganiser. La première sera la couverture.</p></div></div><div class="media-grid" id="media-grid">${images.map((url,i)=>`<figure draggable="true" data-image-index="${i}" data-path="${p.imagePaths?.[i]||''}"><img src="${url}" alt=""><figcaption>${i===0?'Photo de couverture':'Photo '+(i+1)}</figcaption><button type="button" class="remove-media" data-remove-image="${i}" aria-label="Supprimer la photo">×</button></figure>`).join('')}<label class="upload-tile">＋<input id="image-uploader" type="file" accept="image/*" multiple hidden><span>Ajouter des photos</span></label></div></section>
  <section class="publish-box"><span class="publish-icon">↥</span><h3>Prêt à publier ?</h3><p>Les biens publiés sont immédiatement visibles sur le site public Kader Immo.</p><button class="primary-button full" type="submit" data-save="publish">Publier le bien</button><button class="ghost-button full" type="submit" data-save="draft">Enregistrer le brouillon</button></section><section class="activity-box"><h3>Activité du bien</h3><div><span>Créé le</span><b>${displayDate(p.createdAt)}</b></div><div><span>Dernière modification</span><b>${displayDate(p.updatedAt)}</b></div><div><span>Publié le</span><b>${displayDate(p.publishedAt)}</b></div></section></aside></div>
  <div class="editor-footer"><a href="#/admin/listings">Annuler</a><div><button type="submit" class="ghost-button" data-save="draft">Enregistrer le brouillon</button><button type="submit" class="primary-button" data-save="changes">Enregistrer les modifications</button></div></div></form>`);
}
function adminDashboard() {
 const path = currentRoute().replace('/admin','').replace(/^\//,'') || 'dashboard';
 if (!cms.user) return adminLogin();
 if (path==='listings') return listingManagementFr();
 if (path.startsWith('preview/')) return detail(path.split('/')[1]);
 if (path==='media') return dashShell('content','<h1>Médiathèque</h1><p>Vous pouvez supprimer définitivement ici les photos qui ne sont associées à aucun bien.</p><div id="media-library">Mise à jour en cours…</div>');
 if (path==='support') return dashShell('settings', '<h1>Aide et assistance</h1><div class="dash-card"><h2>Gérer votre site internet</h2><p>Biens → Ajouter un bien → saisissez les informations et ajoutez les photos. Choisissez Disponible, Vendu ou Loué avant de publier. Enregistrer le brouillon conserve le bien hors ligne. Enregistrer les modifications conserve son état de publication.</p><p>Utilisez le menu d’actions d’un bien pour l’archiver, le restaurer, le dupliquer ou le supprimer. La première photo sert de couverture. Supprimez les fichiers inutilisés depuis la médiathèque.</p><p>Pour réinitialiser votre mot de passe ou résoudre un problème technique, contactez la personne chargée de la maintenance du site. Ne communiquez jamais votre mot de passe.</p><a href="#/admin/listings">Ouvrir la liste des biens →</a></div>');
 if (path==='settings') return dashShell('settings', '<h1>Compte</h1><p>Connecté avec : '+escapeHtml(cms.user.email)+'</p><button class="primary-button" data-logout>Se déconnecter</button>');
 if (path==='editor') return editorPageFr();
 if (path.startsWith('editor/')) return editorPageFr(path.split('/')[1]);
 return dashboardHome();
}
